// Cycle 0 (start): Z, q, r are formed and loaded (z = -r, Y = Y0); cycles 1 .. 5: one rotation each;
// Latency 6 = 5 iterations + 1: start in cycle t gives done = 1 (one cycle) and busy = 0 in cycle t + 6.
// y is formed from the working registers (round shift by q + g); it is valid from done and held until the next start is accepted.
// Back to back: a new start may be given in the done cycle (one result every 6 cycles).
//
// Constants (cordic_constants): C = 104858, P = 16, L = 44, Y0 = 77
//   indices i = [1, 2, 3, 4, 4]
//   A_i       = [35, 16, 8, 4, 4]
// Widths: Y 7 bits, z 7 bits (two's complement), from the exhaustive ranges over n = 0 .. 255.

module cordic_iter_r1_fo4_m5g2 (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        start,
  input  wire [7:0]  n,
  output reg         busy,
  output reg         done,
  output wire [4:0]  y
);
  // angle: Z = (n*C + 2^(P-1)) >> P (constant multiplier)
  wire [24:0] a_prod = {17'd0, n} * 25'd104858;
  wire [24:0] a_sum  = a_prod + 25'd32768;
  wire [8:0] Z      = a_sum[24:16];
  // range reduction: q = floor(Z / L) by comparison with the multiples of L = 44 (q <= 5 used; q > 5 is underflow)
  reg  [2:0] q_c;
  reg  [8:0] qL_c;
  always @(*) begin
    q_c  = 3'd0;
    qL_c = 9'd0;
    if (Z >= 9'd44) begin q_c = 3'd1; qL_c = 9'd44; end
    if (Z >= 9'd88) begin q_c = 3'd2; qL_c = 9'd88; end
    if (Z >= 9'd132) begin q_c = 3'd3; qL_c = 9'd132; end
    if (Z >= 9'd176) begin q_c = 3'd4; qL_c = 9'd176; end
    if (Z >= 9'd220) begin q_c = 3'd5; qL_c = 9'd220; end
  end
  wire under_c = (Z >= 9'd264);   // q > Fo + 1: output 0
  wire [8:0] r_full = Z - qL_c;
  wire [5:0] r_c    = r_full[5:0];

