  (* fsm_encoding = "none" *) reg [2:0] cnt;

  // iteration table: shift index i and angle constant A_i of iteration cnt (a selection chain, not a
  // case statement: Yosys turns a constant case behind a register into a ROM with a duplicated register)
  wire [2:0] i_cur;
  wire [6:0] a_cur;
  assign i_cur =
    (cnt == 3'd0) ? 3'd1 :
    (cnt == 3'd1) ? 3'd2 :
    (cnt == 3'd2) ? 3'd3 :
    (cnt == 3'd3) ? 3'd4 :
    3'd4;
  assign a_cur =
    (cnt == 3'd0) ? 7'd35 :
    (cnt == 3'd1) ? 7'd16 :
    (cnt == 3'd2) ? 7'd8 :
    (cnt == 3'd3) ? 7'd4 :
    7'd4;

  // one rotation: d = +1 if z >= 0; Y += d (Y >> i); z -= d A_i
  wire        d      = ~zr[6];
  wire [6:0] ysh    = Yr >> i_cur;
  wire [6:0] y_next = Yr + (ysh ^ {7{~d}}) + {6'd0, ~d};
  wire [6:0] z_next = zr + (a_cur ^ {7{d}}) + {6'd0, d};
  wire [6:0] z_ifull = 7'd0 - {1'd0, r_c};   // -r
  wire [6:0] z_init = z_ifull[6:0];

  // control: start is accepted when busy = 0; busy covers the iterations; done pulses for one cycle
  wire last = (cnt == 3'd4);
  always @(posedge clk) begin
    if (!rst_n) begin
      busy <= 1'b0;
      done <= 1'b0;
    end else begin
      done <= busy & last;
      if (!busy) busy <= start;
      else if (last) busy <= 1'b0;
    end
  end

  always @(posedge clk) begin
    if (!busy) begin
      if (start) begin
        Yr  <= 7'd77;
        zr  <= z_init;
        qr  <= q_c;
        ur  <= under_c;
        cnt <= 3'd0;
      end
    end else begin
      Yr  <= y_next;
      zr  <= z_next;
      cnt <= cnt + 3'd1;
    end
  end

  // output: round shift by q + g (y = ((({Y,0} >> s) + 1) >> 1)), clamp to 2^Fo, 0 on underflow
  wire [7:0] o_yx = {Yr, 1'b0};
  reg  [5:0] o_t;
  always @(*) begin
    case (qr)
      3'd0: o_t = o_yx[7:2];
      3'd1: o_t = {1'd0, o_yx[7:3]};
      3'd2: o_t = {2'd0, o_yx[7:4]};
      3'd3: o_t = {3'd0, o_yx[7:5]};
      3'd4: o_t = {4'd0, o_yx[7:6]};
      3'd5: o_t = {5'd0, o_yx[7:7]};
      default: o_t = 6'd0;
    endcase
  end
  wire [6:0] o_tp1 = {1'b0, o_t} + 7'd1;
  wire [5:0] o_yr  = o_tp1[6:1];
  wire [4:0] y_c = ur ? 5'd0 : ((o_yr > 6'd16) ? 5'd16 : o_yr[4:0]);

  assign y = y_c;
endmodule
